import React from "react";

function MainMenu() {
    // Define the styles that were missing in your snippet
    const containerStyle = {
        display: "flex",
        gap: "20px",
        padding: "20px",
        flexWrap: "wrap"
    };

    const itemStyle = {
        padding: "20px",
        borderRadius: "20px",
        backgroundColor: "#fff",
        boxShadow: "0 4px 15px rgba(0,0,0,0.05)",
        width: "150px",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        textAlign: "center",
        cursor: "pointer"
    };

    // The critical fix: You must RETURN the JSX
    return (
        <div style={containerStyle}>
            {[
                { label: "Calendar", icon: "calendar_today", color: "#4834d4" },
                { label: "Layout", icon: "grid_view", color: "#eb4d4b" },
                { label: "Events", icon: "event", color: "#6ab04c" },
                { label: "Stats", icon: "insights", color: "#f0932b" },
            ].map((item) => (
                <div key={item.label} style={itemStyle}>
                    <div
                        style={{
                            width: 50,
                            height: 50,
                            borderRadius: 15,
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                            marginBottom: 15,
                            background: `${item.color}15`, // Light hex transparency
                            color: item.color,
                        }}
                    >
                        <span className="material-icons-round">{item.icon}</span>
                    </div>
                    <div style={{ fontWeight: "bold", fontSize: "1rem" }}>
                        {item.label}
                    </div>
                    <div style={{ fontSize: "0.75rem", color: "#95a5a6", marginTop: 4 }}>
                        Manage {item.label.toLowerCase()}
                    </div>
                </div>
            ))}
        </div>
    );
}

export default MainMenu;
